def frame(canvas,doc):
 w,h=A4
 canvas.setFillColor(HexColor('#111827'));canvas.rect(0,h-49,w,49,fill=1,stroke=0)
 canvas.setFillColor(HexColor('#D1A22C'));canvas.rect(0,h-53,w,4,fill=1,stroke=0)
 canvas.setFillColor(white);canvas.setFont('GuideSans-Bold',10);canvas.drawString(44,h-29,'AUCKLAND KNIGHTS CHESS CLUB')
 canvas.setStrokeColor(HexColor('#D7DFE8'));canvas.line(44,42,w-44,42)
 canvas.setFont('GuideSans',8);canvas.setFillColor(HexColor('#667085'));canvas.drawString(44,29,f'Website documentation | Rev {VERSION} | {DATE}')
 canvas.drawRightString(w-44,29,f'{doc.page}')

def build(filename,title,pages):
 target=OUT/filename;OUT.mkdir(parents=True,exist_ok=True)
 doc=SimpleDocTemplate(str(target),pagesize=A4,leftMargin=44,rightMargin=44,topMargin=75,bottomMargin=58,title=f'Auckland Knights - {title}',author='Auckland Knights Chess Club',pageCompression=1)
 story=[]
 for i,(heading,sections) in enumerate(pages):
  if i:story.append(PageBreak())
  story.append(Paragraph(escape(title),styles['GuideTitle']))
  story.append(Paragraph(f'Revision {VERSION} | Updated {DATE} | {i+1} / {len(pages)}',styles['GuideMeta']))
  story.append(Paragraph(escape(heading),styles['Heading2']))
  for sub,text in sections:
   story.append(KeepTogether([Paragraph(escape(sub),styles['GuideSub']),Paragraph(escape(text),styles['GuideBody'])]))
 doc.build(story,onFirstPage=frame,onLaterPages=frame)
 print(target)

if __name__=='__main__':
 build('akcc_admin_super_admin_user_guide.pdf','Admin & Super Admin User Guide',ADMIN)
 build('akcc_deployment_guide.pdf','Deployment Guide',DEPLOY)
